#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;

    int max_val = 0;
    long long sum = 0;

    for (int i = 0; i < n; ++i) {
        int k;
        cin >> k;
        max_val = max(max_val, k);
        sum += k;
    }

    int ans2 = m + max_val;
    int ans1 = max(max_val, static_cast<int>((sum + m + n - 1) / n));

    cout << ans1 << " " << ans2 << endl;

    return 0;
}

